import{_ as h,o as t,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Mastery Learning","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/mastery-learning.md","filePath":"ideas/mastery-learning.md"}'),c={name:"ideas/mastery-learning.md"};function g(r,n,o,e,s,l){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="mastery-learning" tabindex="-1">Mastery Learning <a class="header-anchor" href="#mastery-learning" aria-label="Permalink to &quot;Mastery Learning&quot;">​</a></h1><p>Trên trang này# Mastery Learning <a href="#mastery-learning">​</a> Không đi tiếp cho tới khi phần hiện tại đã thật sự vững. Nghe rất giống competency-based, và hai cái có họ hàng — nhưng mastery learning tập trung vào một cơ chế cụ thể: <strong>vòng lặp dạy → đo → dạy lại phần còn hụt</strong>.</p><h2 id="bai-toan-no-sinh-ra-đe-giai-​" tabindex="-1">Bài toán nó sinh ra để giải <a href="#bai-toan-no-sinh-ra-đe-giai">​</a> <a class="header-anchor" href="#bai-toan-no-sinh-ra-đe-giai-​" aria-label="Permalink to &quot;Bài toán nó sinh ra để giải [​](#bai-toan-no-sinh-ra-đe-giai)&quot;">​</a></h2><p>Trong lớp học thông thường, bài kiểm tra là <strong>điểm kết thúc</strong> của một chương: thi xong, ghi điểm, sang chương mới. Học sinh được 6 điểm mang theo 40% chưa hiểu sang chương tiếp theo, và không có cơ chế nào quay lại. Mastery learning coi bài kiểm tra là <strong>điểm giữa</strong>: nó chỉ ra ai còn hụt phần nào, rồi phần đó được dạy lại — bằng cách khác — cho đúng những người cần, trước khi cả lớp đi tiếp.</p><h2 id="vong-lap-​" tabindex="-1">Vòng lặp <a href="#vong-lap">​</a> <a class="header-anchor" href="#vong-lap-​" aria-label="Permalink to &quot;Vòng lặp [​](#vong-lap)&quot;">​</a></h2><p>textDạy cả nhóm ↓ Đo nhanh (không tính điểm) ↓ Đã vững? ── Rồi ──→ Bài mở rộng / đào sâu │ └─ Chưa ──→ Dạy lại phần hụt, bằng cách KHÁC ──→ Đo lại ↺Hai chi tiết quyết định thành bại: <strong>Phép đo không tính điểm.</strong> Nếu nó tính điểm, học sinh sẽ giấu chỗ chưa hiểu, và toàn bộ vòng lặp mất tác dụng ngay từ bước đầu. <strong>Dạy lại phải bằng cách khác.</strong> Giảng lại y hệt, chậm hơn và to hơn, là cách phổ biến nhất và cũng vô ích nhất. Nếu cách trình bày đó đã không hiệu quả lần đầu, không có lý do gì để nó hiệu quả lần hai.</p><h2 id="bang-chung-​" tabindex="-1">Bằng chứng <a href="#bang-chung">​</a> <a class="header-anchor" href="#bang-chung-​" aria-label="Permalink to &quot;Bằng chứng [​](#bang-chung)&quot;">​</a></h2><p>Mastery learning là một trong những can thiệp giáo dục được nghiên cứu kỹ nhất, và kết quả khá nhất quán: <strong>hiệu quả rõ rệt, mạnh nhất với những học sinh yếu nhất, và mạnh nhất ở các môn có thứ tự chặt</strong> — toán, ngôn ngữ, lập trình. Điều này hợp lý. Ở những môn mà mỗi bước đứng trên bước trước, việc ngăn lỗ hổng đi tiếp có giá trị cộng dồn qua nhiều năm.</p><h2 id="cai-gia-​" tabindex="-1">Cái giá <a href="#cai-gia">​</a> <a class="header-anchor" href="#cai-gia-​" aria-label="Permalink to &quot;Cái giá [​](#cai-gia)&quot;">​</a></h2><p><strong>Thời gian.</strong> Đây là cái giá thật và không thể tránh. Nếu một phần ba lớp cần học lại chương 3, cả lớp chậm lại. Trong một chương trình có lịch cố định và phải thi cuối kỳ đúng ngày, điều này rất khó thu xếp. <strong>Cần nhiều cách dạy cho cùng một nội dung.</strong> &quot;Dạy lại bằng cách khác&quot; đòi hỏi giáo viên có sẵn hai ba cách trình bày khác nhau cho mỗi khái niệm. Đây là công chuẩn bị lớn. <strong>Rủi ro mắc kẹt.</strong> Nếu một học sinh không vượt qua sau ba bốn vòng, tiếp tục lặp là sai. Cần cơ chế nhận ra rằng vấn đề nằm ở chỗ khác — thường là ở một kiến thức nền xa hơn về trước.</p><h2 id="vi-sao-may-tinh-hop-voi-viec-nay-​" tabindex="-1">Vì sao máy tính hợp với việc này <a href="#vi-sao-may-tinh-hop-voi-viec-nay">​</a> <a class="header-anchor" href="#vi-sao-may-tinh-hop-voi-viec-nay-​" aria-label="Permalink to &quot;Vì sao máy tính hợp với việc này [​](#vi-sao-may-tinh-hop-voi-viec-nay)&quot;">​</a></h2><p>Trở ngại lớn nhất của mastery learning trong lớp học truyền thống là <strong>hậu cần</strong>: một giáo viên không thể đồng thời dạy lại cho mười em và cho hai mươi em khác học tiếp. Với hệ thống học cá nhân hoá, trở ngại đó biến mất. Mỗi learner có vòng lặp riêng; không ai phải chờ ai, và không ai bị kéo đi khi chưa sẵn sàng. Đây là một trong số ít trường hợp mà công nghệ thật sự tháo được một nút thắt cũ, thay vì chỉ số hoá cách làm cũ.</p><h2 id="nemo12-lam-gi-​" tabindex="-1">Nemo12 làm gì <a href="#nemo12-lam-gi">​</a> <a class="header-anchor" href="#nemo12-lam-gi-​" aria-label="Permalink to &quot;Nemo12 làm gì [​](#nemo12-lam-gi)&quot;">​</a></h2><p><strong>Lỗ hổng nền được ưu tiên hơn bài mới.</strong> Nếu một mắt xích nền đang chặn nhiều thứ phía sau, nó luôn thắng về mức ưu tiên so với chương đang học trên lớp — kể cả khi nó thuộc chương trình của hai lớp trước. <strong>Đo lại luôn là bằng cách khác.</strong> Sai nhiều lần cùng một dạng không dẫn tới thêm bài cùng dạng. Hệ thống đổi cách trình bày, quay về bài mẫu giải sẵn, hoặc lùi về kiểm tra kiến thức nền. <strong>Có điểm dừng.</strong> Nếu learner vẫn không vượt qua sau khi đã hạ độ khó và thêm hỗ trợ, hệ thống <strong>ngừng lặp</strong> và chuyển sang truy tìm nguyên nhân thật ở các mắt xích trước đó. Lặp mãi một chỗ là dấu hiệu chẩn đoán sai, không phải dấu hiệu cần cố thêm. <strong>Không thông báo cho ai.</strong> Việc con đang vá một kiến thức của lớp dưới không hiện ra như một thất bại — nó chỉ là việc cần làm. Điều này giải thích một chuyện hay gặp Con học thêm Toán ba buổi một tuần suốt một học kỳ mà không khá lên. Rất thường xuyên, nguyên nhân là lớp học thêm đang dạy đúng nội dung trên lớp — trong khi chỗ đứt thật nằm ở hai năm trước. Thêm giờ vào đúng chỗ sai không tạo ra kết quả nào. Mastery learning không phải học chậm. Nó là không xây tiếp trên nền đang nứt. <a href="/ideas/constructivism">Constructivism →</a></p>',14)])])}const p=h(c,[["render",g]]);export{u as __pageData,p as default};
